  current:()=>CanonicalSchemaDocument;setQuery:(value:string)=>void;setPropertyFilter:(value:CanonicalSchemaRenderContext["propertyFilter"])=>void;setPropertySort:(value:CanonicalSchemaRenderContext["propertySort"])=>void;setFeedback:(value:string)=>void;setMenuPropertyId:(value:string|undefined)=>void;ensureWorking:(node:CanonicalPropertyNode)=>void;commitInline:(node:CanonicalPropertyNode,facet:SchemaTableEditableFacet,value:string)=>SchemaTableQuickEditResult;cancelInline:()=>void;inlineDiagnostic:(message:string)=>void;quickEditRoot:()=>ParentNode;quickEditScope:string;selectedNode:(document:CanonicalSchemaDocument)=>CanonicalPropertyNode|undefined;openProperty:(node:CanonicalPropertyNode,focus?:HTMLElement,section?:FocusedPropertySection)=>void;dismissOverlay:()=>void;command:(command:Parameters<CanonicalSchemaEditorOptions["dispatch"]>[0])=>unknown;render:()=>void;renderMenu:(node:CanonicalPropertyNode)=>HTMLElement;renderFocusedEditor:(document:CanonicalSchemaDocument,node:CanonicalPropertyNode)=>HTMLElement;
