  const {dom,options,document}=context,priorScroll=options.host.querySelector<HTMLElement>("[data-schema-editor-scroll-region]"),retainedScroll=priorScroll?{top:priorScroll.scrollTop,left:priorScroll.scrollLeft}:undefined,retainedTable=document.view==="table"?options.host.querySelector<HTMLTableElement>('table[data-canonical-view="table"]'):null;if(retainedTable)context.tableElement=retainedTable;else delete context.tableElement;clearSchemaTableOverlay(options.host);options.host.replaceChildren();options.host.setAttribute("aria-label",`${options.surface} canonical schema editor`);options.host.dataset.canonicalSchemaId=document.id;options.host.dataset.canonicalRevision=String(document.revision);options.host.dataset.canonicalEditorMode="focused-property";
